const cp = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');
const ROOT = process.cwd();
const { compileRegistry } = require(path.join(ROOT, '.skilled/bin/lib/compiled-routing/009-parent-hub-rollout/001-sk-code/lib/registry-compiler.cjs'));
const HEAD = process.argv[2] || 'HEAD';
function show(p) { return cp.execFileSync('git', ['show', `${HEAD}:${p}`], { cwd: ROOT, maxBuffer: 64 * 1024 * 1024 }); }
const src = {
  'SKILL.md': show('.skilled/skills/sk-code/SKILL.md'),
  'hub-router.json': show('.skilled/skills/sk-code/hub-router.json'),
  'mode-registry.json': show('.skilled/skills/sk-code/mode-registry.json'),
  'ROUTER.md': show('.skilled/skills/sk-code/ROUTER.md'),
};
const MACHINE_ROUTER_HEADING_RE = /^##\s+(?:\d+\.\s+)?MACHINE ROUTER\s*$/;
const FENCE_OPEN_RE = /^ {0,3}(`{3,}|~{3,})/;
const FENCE_CLOSE_RE = /^ {0,3}(`{3,}|~{3,})[ \t]*\r?$/;
function machineRouterSection(text) {
  let fence = null, offset = 0;
  for (const line of text.split('\n')) {
    if (fence === null) {
      const opener = FENCE_OPEN_RE.exec(line);
      if (opener) fence = opener[1];
      else if (MACHINE_ROUTER_HEADING_RE.test(line)) return text.slice(offset);
    } else {
      const closer = FENCE_CLOSE_RE.exec(line);
      if (closer && closer[1][0] === fence[0] && closer[1].length >= fence.length) fence = null;
    }
    offset += line.length + 1;
  }
  return null;
}
const fixture = JSON.parse(fs.readFileSync(path.join(ROOT, '.skilled/bin/lib/compiled-routing/009-parent-hub-rollout/001-sk-code/fixtures/canary-cases.v1.json'), 'utf8'));
const routerMarkdown = machineRouterSection(src['ROUTER.md'].toString('utf8'));
const snap = compileRegistry({
  activationGeneration: fixture.activationGeneration,
  hubRouter: JSON.parse(src['hub-router.json'].toString('utf8')),
  registry: JSON.parse(src['mode-registry.json'].toString('utf8')),
  ...(routerMarkdown !== null ? { routerMarkdown } : {}),
  skillMarkdown: src['SKILL.md'].toString('utf8'),
  sourceBytes: src,
});
console.log('generation', snap.policy.activationGeneration, 'hash', snap.policy.effectivePolicyHash);
EOF
